  "ch3.lab.usb10": "USB 10Gbps",
  "ch3.lab.usb32g1x2": "USB 3.2 Gen 1×2",
  "ch3.lab.usb32g2x2": "USB 3.2 Gen 2×2",
  "ch3.lab.usb20g": "USB 20Gbps",
  "ch3.lab.usb4_20": "USB4 20Gbps",
  "ch3.lab.usb4_40": "USB4 40Gbps",
  "ch3.lab.usb80": "USB 80Gbps",
